"use strict";const e=require("./request.js");exports.assignFamilyCook=function(t,n,i){return e.post("/family/assign",{planId:t,dayIndex:n,cookOpenid:i})},exports.createFamily=function(){return e.post("/family")},exports.fetchFamily=function(){return e.get("/family")},exports.fetchFamilyMenus=function(){return e.get("/family/menus")},exports.joinFamily=function(t){return e.post("/family/join",{code:t})},exports.leaveFamily=function(){return e.post("/family/leave")};
